// ── Sunburst Chart: Country → Organisation Citation Structure ────────────────
//
// Loads pre-computed Plotly sunburst figures from assets/data/sunburst_data.json
// (generated by generate_sunburst.py) and renders the selected figure on demand.
// All 12 combinations (6 institutions × 2 directions) are cached in memory after
// the first fetch so switching is instant.

(function () {

  var DIV_ID = 'sunburst-chartdiv';
  var DATA_URL = 'assets/data/sunburst_data.json';

  var _cache = null;       // the full JSON blob — loaded once
  var _rendered = null;    // key of the currently rendered figure

  // ── Theming applied on top of pre-computed layout ──────────────────────────
  function applyTheme(layout) {
    layout = layout || {};

    layout.paper_bgcolor = '#2A0C32';
    layout.plot_bgcolor  = '#2A0C32';

    layout.font = {
      family: 'Inter, sans-serif',
      color: '#FFFFFF',
      size: 12,
    };

    if (layout.title && typeof layout.title === 'object') {
      layout.title.font = {
        family: 'Playfair Display, serif',
        color: '#FFFFFF',
        size: 15,
      };
      layout.title.x = 0.02;
    }

    layout.margin    = { l: 10, r: 10, t: 100, b: 20 };
    layout.autosize  = true;
    delete layout.width;
    layout.height    = 660;

    return layout;
  }

  // ── Render a figure for the given key ──────────────────────────────────────
  function render(key) {
    if (_rendered === key) return;

    var div = document.getElementById(DIV_ID);
    if (!div || !_cache) return;

    var figData = _cache[key];
    if (!figData) {
      console.warn('Sunburst: no figure found for key', key);
      div.innerHTML =
        '<div class="sankey-loading sankey-error" style="color:#f08080;">No data for this selection.</div>';
      return;
    }

    var layout = applyTheme(JSON.parse(JSON.stringify(figData.layout || {})));

    // Clear loading message / previous chart
    div.innerHTML = '';

    Plotly.newPlot(div, figData.data || [], layout, {
      responsive: true,
      displayModeBar: false,
    });

    _rendered = key;
  }

  // ── Load data then render initial view ─────────────────────────────────────
  function init() {
    var div = document.getElementById(DIV_ID);
    if (!div) return;

    var instSel = document.getElementById('sunburst-inst-select');
    var dirSel  = document.getElementById('sunburst-dir-select');
    if (!instSel || !dirSel) return;

    function currentKey() {
      return instSel.value + '__' + dirSel.value;
    }

    fetch(DATA_URL)
      .then(function (r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      })
      .then(function (data) {
        _cache = data;
        render(currentKey());
      })
      .catch(function (err) {
        console.error('Sunburst load error:', err);
        var d = document.getElementById(DIV_ID);
        if (d) {
          d.innerHTML =
            '<div class="sankey-loading sankey-error" style="color:#f08080;">Could not load sunburst data.</div>';
        }
      });

    // ── Dropdown listeners ──────────────────────────────────────────────────
    instSel.addEventListener('change', function () { render(currentKey()); });
    dirSel.addEventListener('change',  function () { render(currentKey()); });
  }

  // ── Bootstrap ──────────────────────────────────────────────────────────────
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

})();
